const eur=new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0});
const money=v=>v===null?'Not quantified':eur.format(v);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human=s=>String(s).replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase());
const evMap=d=>Object.fromEntries(d.evidence.map(e=>[e.id,e]));
const badges=d=>`<span class="pill ${d.reviewTier==='material_judgment'?'amber':'slate'}">${d.reviewTier==='material_judgment'?'Material judgment':'Operational'}</span><span class="pill conf-${d.confidence}">${esc(d.confidence)} confidence</span>${d.agentDisagreement?'<span class="pill red">Agent disagreement</span>':''}${d.changedFromAI?'<span class="pill blue">Student override</span>':''}`;
const evLinks=(d,m)=>d.evidence.map(id=>`<a href="#evidence-${id}" title="${esc(m[id]?.source||id)}">${id}</a>`).join(' ');
const topbar=review=>`<header class="topbar"><a class="brand" href="/"><span class="brand-mark">DPI</span><span>Financial Crime Scene</span></a><nav aria-label="Primary">${review?'<a href="/">Full investigation</a>':'<a href="#overview">Overview</a><a href="#evidence">Evidence</a><a href="#decisions">Decisions</a><a href="#statements">Statements</a>'}<a href="/review/">Assessor review</a><a href="/submission.json">JSON</a></nav></header>`;
const metrics=s=>`<section class="metrics" aria-label="Certified financial highlights"><article><span>Final profit</span><strong>${money(s.profitAndLoss.finalProfit)}</strong></article><article><span>Closing cash</span><strong>${money(s.cashFlow.closingCash)}</strong></article><article><span>Total assets</span><strong>${money(s.balanceSheet.assets.totalAssets)}</strong></article><article><span>Total liabilities</span><strong>${money(s.balanceSheet.liabilities.totalLiabilities)}</strong></article><article><span>Closing equity</span><strong>${money(s.balanceSheet.equity.closingEquity)}</strong></article><article class="reconciled"><span>Balance check</span><strong>${money(s.balanceSheet.balanceCheck)}</strong><small>Reconciled</small></article></section>`;
const effectGrid=e=>`<div class="effect-grid">${Object.entries(e).map(([k,v])=>`<div><span>${human(k)}</span><strong class="${v<0?'negative':v>0?'positive':''}">${money(v)}</strong></div>`).join('')}</div>`;
const materialCard=(d,m,compact=false)=>`<details id="${d.id}" class="decision-card material" ${compact?'open':''} data-id="${d.id}" data-category="${d.category}" data-tier="${d.reviewTier}" data-confidence="${d.confidence}" data-disagreement="${!!d.agentDisagreement}" data-override="${!!d.changedFromAI}"><summary><div><b>${d.id}</b><h3>${esc(d.question)}</h3></div><div class="pill-row">${badges(d)}</div></summary><div class="decision-body"><p class="answer"><span>Certified treatment</span>${esc(d.answer)}</p>${compact?'':`<div class="trail"><div><span>Agent 1 proposal</span><p>${esc(d.aiProposal)}</p></div><div><span>Independent Agent 2 analysis</span><p>${esc(d.independentChallenge)}</p></div><div><span>Why this treatment?</span><p>${esc(d.studentReasoning)}</p></div></div>${effectGrid(d.statementEffect)}`}<footer><span>Evidence</span>${evLinks(d,m)}</footer></div></details>`;
const operationalCard=(d,m)=>`<details id="${d.id}" class="decision-card" data-id="${d.id}" data-category="${d.category}" data-tier="${d.reviewTier}" data-confidence="${d.confidence}" data-disagreement="false" data-override="false"><summary><div><b>${d.id}</b><h3>${esc(d.question)}</h3></div><div class="pill-row">${badges(d)}</div></summary><div class="decision-body"><p class="answer"><span>Final answer</span>${esc(d.answer)}</p><footer><span>Evidence</span>${evLinks(d,m)}</footer></div></details>`;
const statTable=(title,obj)=>`<article class="statement-card"><h3>${title}</h3><table>${Object.entries(obj).map(([k,v])=>typeof v==='object'?`<tr class="group"><th colspan="2">${human(k)}</th></tr>${Object.entries(v).map(([a,b])=>`<tr class="${/total|closing|check/i.test(a)?'total':''}"><td>${human(a)}</td><td>${money(b)}</td></tr>`).join('')}`:`<tr class="${/total|gross profit|operating profit|final profit|closing cash|net cash/i.test(human(k))?'total':''}"><td>${human(k)}</td><td>${money(v)}</td></tr>`).join('')}</table></article>`;
function scheduleCards(s){const cards=[['Revenue & receivables',[['Revenue',s.revenueReceivables.revenueTotal],['Gross AR',s.revenueReceivables.grossAR],['R-17 impairment',s.revenueReceivables.impairment],['Net AR',s.revenueReceivables.netAR],['Customer advances',s.revenueReceivables.customerAdvances]]],['Inventory & COGS',[['Opening inventory',s.inventoryCOGS.openingInventory],['Purchases',s.inventoryCOGS.purchases],['Expected inventory',s.inventoryCOGS.rollForwardExpected],['System/physical count',s.inventoryCOGS.systemPhysical],['Unexplained difference',s.inventoryCOGS.unexplainedDifference],['Damaged stock',s.inventoryCOGS.damagedStock],['Saleable inventory',s.inventoryCOGS.saleableInventory],['Materials COGS',s.inventoryCOGS.materialsCOGS]]],['Purchases & payables',[['Opening AP (reconstructed)',s.purchasesPayables.openingPayablesReconstructed],['Purchases',s.purchasesPayables.purchases],['Supplier payments',-s.purchasesPayables.supplierPayments],['Closing AP',s.purchasesPayables.closingPayables]]],['Payroll',[['Opening payable',s.payroll.openingPayable],['Expense',s.payroll.expense],['Cash paid',-s.payroll.cashPaid],['Closing payable',s.payroll.closingPayable],['Founder amount excluded',s.payroll.founderClaimedBonusExcluded]]],['PPE & depreciation',[['Opening cost',s.ppe.openingCost],['Additions',s.ppe.additions],['Closing cost',s.ppe.closingCost],['Closing accumulated depreciation',-s.ppe.closingAccumulatedDepreciation],['Closing NBV',s.ppe.closingNBV]]],['Debt & interest',[['Opening loan',s.debtInterest.openingLoan],['New borrowing',s.debtInterest.newBorrowing],['Principal repayment',-s.debtInterest.principalRepayment],['Closing loan',s.debtInterest.closingLoan],['Interest payable',s.debtInterest.interestPayable]]],['Equity',[['Opening equity',s.equity.openingEquity],['Profit',s.equity.profit],['Owner distributions',-s.equity.ownerDistributions],['Closing equity',s.equity.closingEquity]]]];return cards.map(([t,rows])=>`<article class="schedule-card panel"><h3>${t}</h3>${rows.map(([a,b])=>`<div><span>${a}</span><b>${money(b)}</b></div>`).join('')}</article>`).join('')}
const controls=d=>`<div class="decision-controls panel"><label class="search"><span>Search decisions</span><input id="decision-search" type="search" placeholder="ID, question or answer"></label><label><span>Category</span><select id="category-filter"><option value="all">All categories</option>${[...new Set(d.decisions.map(x=>x.category))].map(x=>`<option value="${x}">${human(x)}</option>`).join('')}</select></label><label><span>Review tier</span><select id="tier-filter"><option value="all">All tiers</option><option value="material_judgment">Material judgment</option><option value="operational">Operational</option></select></label><label><span>Confidence</span><select id="confidence-filter"><option value="all">All confidence</option><option>high</option><option>medium</option><option>low</option></select></label><label class="check"><input id="disagreement-filter" type="checkbox"> Agent disagreement</label><label class="check"><input id="override-filter" type="checkbox"> Student override</label><div class="decision-actions"><button id="expand-decisions" type="button">Expand shown</button><button id="collapse-decisions" type="button">Collapse all</button></div><span id="result-count" class="result-count">100 shown</span></div>`;
function renderMain(d){const m=evMap(d),mat=d.decisions.filter(x=>x.reviewTier==='material_judgment'),low=d.decisions.filter(x=>x.confidence==='low'),dis=d.decisions.filter(x=>x.agentDisagreement),ov=d.decisions.filter(x=>x.changedFromAI);document.querySelector('#app').innerHTML=`${topbar(false)}<main><section id="overview" class="masthead"><div><p class="eyebrow">CASE ${d.caseId} · 31 AUGUST 2026 · EUR</p><h1>Certified reconstruction</h1><p class="lede">Evidence-led accounts, 100 documented decisions and a visible trail from AI proposals to the student's certified treatment.</p></div><div class="balance-seal"><span>Balance check</span><strong>${money(d.statements.balanceSheet.balanceCheck)}</strong><small>Reconciled</small></div></section>${metrics(d.statements)}<section class="case-status panel"><div><b>100 / 100</b><span>decisions complete</span></div><div><b>${mat.length} / 25</b><span>material judgments</span></div><div><b>${dis.length}</b><span>agent disagreement</span></div><div><b>${ov.length}</b><span>student override</span></div><div><b>${low.length}</b><span>low confidence</span></div><div><b>${d.uncertainties.length}</b><span>unresolved uncertainties</span></div></section><section id="evidence" class="section-block"><div class="section-head"><div><p class="eyebrow">EVIDENCE REGISTER</p><h2>Source strength before convenience</h2></div><p class="section-note">Bank, signed and third-party evidence generally outweigh management spreadsheets and messages.</p></div><div class="evidence-grid">${d.evidence.map(e=>`<article id="evidence-${e.id}" class="evidence-card panel"><div><b>${e.id}</b><span class="pill slate">${esc(e.reliability)}</span></div><h3>${esc(e.source)}</h3><p>${esc(e.description)}</p><small>${esc(e.type)}</small></article>`).join('')}</div></section><section id="decisions" class="section-block"><div class="section-head"><div><p class="eyebrow">DECISION EXPLORER</p><h2>Every conclusion is traceable</h2></div></div>${controls(d)}<div id="decision-list" class="decision-list">${d.decisions.map(x=>x.reviewTier==='material_judgment'?materialCard(x,m):operationalCard(x,m)).join('')}</div><div id="empty-decisions" class="empty" hidden>No decisions match these filters.</div></section><section id="schedules" class="section-block"><div class="section-head"><div><p class="eyebrow">SUPPORTING SCHEDULES</p><h2>How the accounts were reconstructed</h2></div></div><div class="schedule-grid">${scheduleCards(d.schedules)}</div></section><section id="statements" class="section-block"><div class="section-head"><div><p class="eyebrow">CERTIFIED STATEMENTS</p><h2>Three statements at 31 August 2026</h2></div></div><div class="statement-grid">${statTable('Profit and loss',d.statements.profitAndLoss)}${statTable('Cash flow',d.statements.cashFlow)}${statTable('Balance sheet',d.statements.balanceSheet)}</div></section><section id="reconciliations" class="section-block"><div class="section-head"><div><p class="eyebrow">RECONCILIATION ENGINE</p><h2>Calculated checks, not labels</h2></div></div><div class="recon-grid">${d.reconciliations.map(r=>`<article class="recon-card panel"><span class="status-dot ${r.status==='PASS'?'green':'red'}"></span><b>${r.name}</b><code>${r.calculation}</code><div><strong>${money(r.actual)}</strong><span class="pill ${r.status==='PASS'?'green':'red'}">${r.status}</span></div></article>`).join('')}</div></section><section id="uncertainties" class="section-block"><div class="section-head"><div><p class="eyebrow">UNRESOLVED</p><h2>Contradictions kept visible</h2></div></div><div class="uncertainty-grid">${d.uncertainties.map(u=>`<article class="uncertainty panel"><span>${u.id}</span><h3>${u.title}</h3><strong>${money(u.amount)}</strong><p>${u.detail}</p></article>`).join('')}</div></section><section id="trail" class="section-block"><div class="section-head"><div><p class="eyebrow">AI REVIEW TRAIL</p><h2>25 material judgments</h2></div><p class="section-note">Agent 2 reached an independent position from the original evidence before comparison.</p></div><div class="decision-list material-only">${mat.map(x=>materialCard(x,m)).join('')}</div></section><section id="board" class="section-block board-panel"><p class="eyebrow">BOARD RECOMMENDATION</p><h2>${esc(d.boardRecommendation.headline)}</h2><div class="board-numbers"><span>Management claim <b>${money(d.boardRecommendation.managementClaimedProfit)}</b></span><span>Certified profit <b>${money(d.boardRecommendation.certifiedProfit)}</b></span></div><a class="button" href="/review/">Open assessor review</a></section></main><footer>Divorce Party International Ltd. · Forensic accounting reconstruction · Local pre-deployment review · Student identity required</footer>`;wireFilters()}
function renderReview(d){const m=evMap(d),mat=d.decisions.filter(x=>x.reviewTier==='material_judgment'),dis=d.decisions.filter(x=>x.agentDisagreement),ov=d.decisions.filter(x=>x.changedFromAI),low=d.decisions.filter(x=>x.confidence==='low');document.querySelector('#app').innerHTML=`${topbar(true)}<main><section class="review-title"><div><p class="eyebrow">ASSESSOR REVIEW · ${d.caseId}</p><h1>Critical case review</h1><p class="lede">Compact view of the certified results, material judgments, exceptions and board conclusion.</p></div><div class="student-warning"><b>Student identity required</b><span>${esc(d.student.id)} · ${esc(d.student.name)}</span></div></section>${metrics(d.statements)}<section class="review-grid"><div><section class="review-section"><div class="section-head"><div><p class="eyebrow">PRIORITY 1</p><h2>25 material judgments</h2></div></div><div class="decision-list">${mat.map(x=>materialCard(x,m,true)).join('')}</div></section></div><aside><section class="side-section panel"><p class="eyebrow">AGENT DISAGREEMENTS</p>${dis.map(x=>`<a href="#${x.id}"><b>${x.id}</b> ${esc(x.question)}</a>`).join('')||'<p>None</p>'}</section><section class="side-section panel"><p class="eyebrow">STUDENT OVERRIDES</p>${ov.map(x=>`<p><b>${x.id}</b> Final treatment differs from Agent 1.</p>`).join('')||'<p>None</p>'}</section><section class="side-section panel"><p class="eyebrow">LOW CONFIDENCE</p><p><b>${low.length} decisions</b>, mainly monthly payroll allocation and absent insurance evidence.</p>${low.map(x=>`<span>${x.id}</span>`).join(' ')}</section><section class="side-section panel"><p class="eyebrow">UNCERTAINTIES</p>${d.uncertainties.map(u=>`<div><b>${u.title}</b><p>${u.detail}</p></div>`).join('')}</section><section class="side-section panel"><p class="eyebrow">RECONCILIATIONS</p>${d.reconciliations.map(r=>`<div class="mini-recon"><span>${r.name}</span><b class="${r.status==='PASS'?'ok':'bad'}">${r.status}</b></div>`).join('')}</section></aside></section><section class="section-block"><div class="section-head"><div><p class="eyebrow">FINAL STATEMENTS</p><h2>Certified financial position</h2></div></div><div class="statement-grid">${statTable('Profit and loss',d.statements.profitAndLoss)}${statTable('Cash flow',d.statements.cashFlow)}${statTable('Balance sheet',d.statements.balanceSheet)}</div></section><section class="board-panel"><p class="eyebrow">BOARD RECOMMENDATION</p><h2>${esc(d.boardRecommendation.headline)}</h2></section></main><footer>Assessor review · Full machine-readable answer at <a href="/submission.json">/submission.json</a></footer>`}
function wireFilters(){const cards=[...document.querySelectorAll('#decision-list .decision-card')],search=document.querySelector('#decision-search'),cat=document.querySelector('#category-filter'),tier=document.querySelector('#tier-filter'),conf=document.querySelector('#confidence-filter'),dis=document.querySelector('#disagreement-filter'),ov=document.querySelector('#override-filter'),count=document.querySelector('#result-count'),empty=document.querySelector('#empty-decisions');const run=()=>{let shown=0;cards.forEach(c=>{const ok=c.textContent.toLowerCase().includes(search.value.toLowerCase())&&(cat.value==='all'||c.dataset.category===cat.value)&&(tier.value==='all'||c.dataset.tier===tier.value)&&(conf.value==='all'||c.dataset.confidence===conf.value)&&(!dis.checked||c.dataset.disagreement==='true')&&(!ov.checked||c.dataset.override==='true');c.hidden=!ok;if(ok)shown++});count.textContent=`${shown} shown`;empty.hidden=shown!==0};[search,cat,tier,conf,dis,ov].forEach(x=>x.addEventListener('input',run))}
function wireDecisionExpanders(){document.querySelector('#expand-decisions')?.addEventListener('click',()=>document.querySelectorAll('#decision-list .decision-card:not([hidden])').forEach(x=>x.open=true));document.querySelector('#collapse-decisions')?.addEventListener('click',()=>document.querySelectorAll('#decision-list .decision-card').forEach(x=>x.open=false))}
function enhanceMain(){const status=document.querySelector('.case-status');if(!status)return;status.insertAdjacentHTML('afterend',`<section class="start-here panel"><div><p class="eyebrow">START HERE</p><h2>A simpler review path</h2><p>Open only the level of detail you need. Decision reasoning stays collapsed until selected.</p></div><nav aria-label="Recommended review path"><a href="#statements"><b>1</b><span>Read the three statements</span></a><a href="#uncertainties"><b>2</b><span>Check the three uncertainties</span></a><a href="/review/"><b>3</b><span>Review the 25 key judgments</span></a><a href="#decisions"><b>4</b><span>Search all 100 decisions</span></a></nav></section>`);const evidence=document.querySelector('#evidence'),statements=document.querySelector('#statements'),uncertainties=document.querySelector('#uncertainties');evidence.before(statements);statements.after(uncertainties);document.querySelector('#app>footer').textContent='Divorce Party International Ltd. · Forensic accounting reconstruction · Public review version';wireDecisionExpanders()}
fetch('/submission.json').then(r=>{if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}).then(d=>document.body.dataset.page==='review'?renderReview(d):(renderMain(d),enhanceMain())).catch(e=>{document.querySelector('#app').innerHTML=`<main><div class="error"><h1>Case data could not be loaded</h1><p>${esc(e.message)}</p></div></main>`});
